func TestExtractSummary_EmptyTranscript(t *testing.T) {
	t.Parallel()
	ag := &OpenCodeAgent{}
	emptySession := ExportSession{Info: SessionInfo{ID: "empty"}, Messages: []ExportMessage{}}
	data, err := json.Marshal(emptySession)
