func TestCalculateTokenUsage(t *testing.T) {
	t.Parallel()
	ag := &OpenCodeAgent{}
	path := writeTestTranscript(t, testExportJSON)

	// From offset 0 — both assistant messages
	usage, err := ag.CalculateTokenUsage(path, 0)
